import sys
b1n, b2n = sys.argv[1], sys.argv[2]
def put(path, marker, before, text):
    s = open(path, encoding='utf-8').read()
    if marker in s:
        return
    assert s.count(before) == 1, (path, s.count(before))
    open(path, 'w', encoding='utf-8').write(s.replace(before, text + before))
    print('notes:', path)
